	@Test
	void priorityJoinReplacementRetainsEqualOrdinaryAndIndependentOccurrences() {
		BindingSetAssignment rows = new BindingSetAssignment();
		BindingSet duplicate = new ListBindingSet(List.of("x"), VF.createLiteral(1));
		rows.setBindingSets(List.of(duplicate, duplicate));
		Join first = new Join(rows, new SingletonSet());
		first.setVariableScopeChange(true);
		first.setIndependentInputScope(true);
		Join ordinary = first.clone();
		ordinary.setIndependentInputScope(false);
		Join second = first.clone();
		assertEquals(first, ordinary);
		assertEquals(first, second);
		QueryRoot query = new QueryRoot(new Join(new Join(first, ordinary), second));
		List<String> expected = evaluate(query, List.of());
		assertEquals(8, expected.size(), "All three duplicate-producing occurrences contribute to the bag");
		QueryJoinOptimizer optimizer = new QueryJoinOptimizer(new EvaluationStatistics());
		optimizer.optimize(query, null, EmptyBindingSet.getInstance());
		new ParentReferenceChecker(optimizer).optimize(query, null, EmptyBindingSet.getInstance());
		assertEquals(expected, evaluate(query, List.of()));
		List<TupleExpr> boundaries = new ArrayList<>();
		query.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof TupleExpr tuple && tuple.isIndependentInputScope()) {
					boundaries.add(tuple);
				}
				super.meetNode(node);
			}
		});
		assertEquals(2, boundaries.size());
		assertNotSame(boundaries.get(0), boundaries.get(1));
	}

	@Test
	void loweredGraphInputAuthoritySurvivesWrappersCloneSerializationAndCachedRecipes() throws Exception {
		MapBindingSet invocation = new MapBindingSet();
		invocation.addBinding("g", G1);
		MapBindingSet missingSubject = new MapBindingSet();
		missingSubject.addBinding("g", G1);
		missingSubject.addBinding("s", VF.createIRI("urn:missing"));
		List<BindingSet> inputs = List.of(invocation, BindingSetOrigin.produced(invocation, Set.of("g")),
				BindingSetOrigin.with(invocation, BindingSetOrigin.of(EmptyBindingSet.getInstance())), missingSubject);
		List<List<String>> expectedBags = List.of(
				List.of("{g=urn:g2, o=urn:object, predicate=urn:p, s=urn:subject}"),
				List.of("{g=urn:g2}"), List.of("{g=urn:g2}"), List.of("{g=urn:g2, s=urn:missing}"));
		List<Statement> data = List.of(
				VF.createStatement(VF.createIRI("urn:subject"), VF.createIRI("urn:p"), VF.createIRI("urn:object"), G1),
				VF.createStatement(VF.createIRI("urn:distractor"), VF.createIRI("urn:p"),
						VF.createIRI("urn:wrong-graph-object"), G2));
		for (int wrapper = 0; wrapper < 3; wrapper++) {
			TupleExpr right = new Graph(Var.of("g", G1, false, false), pattern("p"));
			if (wrapper == 1) {
				right = new Filter(right, new Bound(Var.of("s")));
			} else if (wrapper == 2) {
				right = new Extension(right);
			}
			for (int input = 0; input < inputs.size(); input++) {
				Extension left = new Extension(new SingletonSet(), new ExtensionElem(new ValueConstant(G2), "g"));
				if (input == 3) {
					// This subject belongs to the left relation, so an independent RHS miss preserves that row.
					left.addElement(new ExtensionElem(new ValueConstant(VF.createIRI("urn:missing")), "s"));
				}
				QueryRoot original = new QueryRoot(new LeftJoin(left, right.clone()));
				PlanningGraphDomains.capture(original, PlanningGraphDomain.defaultGraph());
				// A runtime REQUEST selector retains request authority. Its local shadow wins the output merge,
				// while GRAPH still selects G1. LOCAL/UNKNOWN inputs remain strict; an absent API subject is unmatched.
				assertGraphAuthorityRoutes(original, data, inputs.get(input), expectedBags.get(input));
			}
		}
		StatementPattern marked = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("s"), Var.of("p"), Var.of("o"), Var.of("graph", G1, true, true));
		marked.setIndependentInputScope(true);
		StatementPattern plain = marked.clone();
		plain.setIndependentInputScope(false);
		assertEquals(marked, plain, "Internal authority does not change public algebra mapping equality");
		assertFalse(PackedQueryCacheIdentity.createPlanIdentity(marked)
				.matches(PackedQueryCacheIdentity.createPlanIdentity(plain)),
				"Behavior-dependent planner identity must distinguish equal physical statements with different authority");
	}

