	@Test
	void graphBodiesRemainSearchableWhileGraphIsAnOuterJoinBoundary() {
		StatementPattern large = new StatementPattern(Var.of("x"),
				Var.of("large", VF.createIRI("urn:large")), Var.of("largeValue"));
		StatementPattern medium = new StatementPattern(Var.of("bridge"),
				Var.of("medium", VF.createIRI("urn:medium")), Var.of("mediumValue"));
		StatementPattern small = new StatementPattern(Var.of("x"),
				Var.of("small", VF.createIRI("urn:small")), Var.of("bridge"));
		Graph graph = new Graph(Var.of("g"), new Join(new Join(large, medium), small));
		PackedCostModel costs = (query, relationId) -> {
			if (!query.isStatementPattern(relationId)) {
				return Double.NaN;
			}
			return switch (query.statementPatternValue(relationId, 1).stringValue()) {
			case "urn:large" -> 1_000.0d;
			case "urn:medium" -> 100.0d;
			case "urn:small" -> 10.0d;
			default -> 1.0d;
			};
		};
		Graph selected = assertInstanceOf(Graph.class,
				PackedCascadesPlanner.optimize(graph, OptimizationGoal.root(), costs).selectedPlan());
		Join first = assertInstanceOf(Join.class, assertInstanceOf(Join.class, selected.getArg()).getLeftArg());
		Set<Value> firstPredicates = Set.of(assertInstanceOf(StatementPattern.class, first.getLeftArg())
				.getPredicateVar()
				.getValue(),
				assertInstanceOf(StatementPattern.class, first.getRightArg())
						.getPredicateVar()
						.getValue());
		assertEquals(Set.of(VF.createIRI("urn:small"), VF.createIRI("urn:medium")), firstPredicates);

		Join outer = new Join(pattern("outer"), graph.clone());
		TupleExpr outerSelected = PackedCascadesPlanner.optimize(outer, OptimizationGoal.root(), costs).selectedPlan();
		Join selectedJoin = assertInstanceOf(Join.class, outerSelected);
		assertTrue(selectedJoin.getLeftArg() instanceof Graph || selectedJoin.getRightArg() instanceof Graph,
				"the Graph wrapper must remain one factor outside its own body");
	}

	@Test
	void retainedNamedGraphDoesNotReadTheDefaultGraphAndConversely() {
		for (boolean populatedNamed : List.of(false, true)) {
			Resource context = populatedNamed ? G1 : null;
			List<Statement> data = List.of(VF.createStatement(VF.createIRI("urn:s"), VF.createIRI("urn:p"),
					VF.createLiteral("value"), context));
			Graph original = new Graph(Var.of("g", G1, false, true), pattern("p"));
			List<String> reference = evaluate(original, data);
			assertEquals(populatedNamed ? 1 : 0, reference.size());
			TupleExpr selected = PackedCascadesPlanner.optimize(original, OptimizationGoal.root()).selectedPlan();
			assertInstanceOf(Graph.class, selected);
			assertEquals(reference, evaluate(selected, data));
		}
	}

